app.json:
{
  "agent": {
    "name": "Desk assistant",
    "file": "agent.md",
    "dock": "open"
  },
  "budget": {
    "per_run": 0.10
  },
  "capabilities": {
    "records": {
      "client": "rw",
      "deliverable": "rw",
      "invoice": "rw",
      "report": "rw",
      "time_entry": "rw"
    },
    "connectors": {
      "gmail": {
        "as": "me",
        "can": [
          "read",
          "search"
        ]
      }
    }
  },
  "commands": [
    {
      "id": "friday-report",
      "label": "Draft Friday reports",
      "run": "friday-report"
    },
    {
      "id": "build-invoice",
      "label": "Build invoice draft",
      "for": "client",
      "run": "build-invoice",
      "params": {
        "client": "$record.id",
        "time": "$record.links"
      }
    },
    {
      "id": "write-invoice",
      "label": "Write invoice (asks first)",
      "for": "invoice",
      "run": "write-invoice",
      "params": {
        "invoice": "$record.id"
      }
    }
  ],
  "id": "01M8DDPFXFKR0G8VH4GX3M1YK5",
  "kit": 2,
  "name": "Client desk",
  "records": {
    "client": {
      "common": "organization",
      "fields": {
        "name": {
          "type": "text",
          "required": true
        }
      },
      "present": {
        "title": "name"
      },
      "title": "name"
    },
    "deliverable": {
      "fields": {
        "client": {
          "type": "ref",
          "to": "client"
        },
        "due_at": {
          "type": "datetime"
        },
        "name": {
          "type": "text",
          "required": true
        },
        "notes": {
          "type": "longtext"
        },
        "owner": {
          "type": "text"
        },
        "status": {
          "type": "enum",
          "values": [
            "Planned",
            "In progress",
            "Blocked",
            "Done"
          ],
          "default": "Planned",
          "required": true
        }
      },
      "present": {
        "title": "name",
        "meta": [
          "client",
          "due_at"
        ],
        "trailing": "status",
        "state": "status"
      },
      "title": "name"
    },
    "invoice": {
      "fields": {
        "name": {
          "type": "text",
          "required": true
        },
        "client": {
          "type": "ref",
          "to": "client"
        },
        "period_start": {
          "type": "date"
        },
        "period_end": {
          "type": "date"
        },
        "amount": {
          "type": "money",
          "currency": "USD"
        },
        "status": {
          "type": "enum",
          "values": [
            "Draft",
            "Approved",
            "Written"
          ],
          "default": "Draft",
          "required": true
        },
        "body": {
          "type": "longtext"
        }
      },
      "present": {
        "title": "name",
        "meta": [
          "client",
          "period_start",
          "period_end"
        ],
        "trailing": "amount",
        "state": "status",
        "money": "amount"
      },
      "title": "name"
    },
    "report": {
      "fields": {
        "name": {
          "type": "text",
          "required": true
        },
        "client": {
          "type": "ref",
          "to": "client"
        },
        "week_ending": {
          "type": "date"
        },
        "body": {
          "type": "longtext"
        },
        "status": {
          "type": "enum",
          "values": [
            "Draft",
            "Reviewed",
            "Sent"
          ],
          "default": "Draft",
          "required": true
        }
      },
      "present": {
        "title": "name",
        "meta": [
          "client",
          "week_ending"
        ],
        "trailing": "status",
        "state": "status"
      },
      "title": "name"
    },
    "time_entry": {
      "fields": {
        "date": {
          "type": "date",
          "required": true
        },
        "client": {
          "type": "ref",
          "to": "client"
        },
        "hours": {
          "type": "number",
          "required": true
        },
        "description": {
          "type": "text",
          "required": true
        },
        "billable": {
          "type": "bool",
          "default": true
        }
      },
      "present": {
        "title": "description",
        "meta": [
          "date",
          "client"
        ]
      },
      "title": "description"
    }
  },
  "triggers": [
    {
      "id": "friday",
      "on": "schedule",
      "cron": "0 16 * * 5",
      "run": "friday-report"
    }
  ],
  "version": 1
}

