{
  "ask": "Track client deliverables and deadlines, draft a Friday status report from mail and Slack per client, roll CSV time into an invoice draft, and ask before writing it to QuickBooks.",
  "data": [
    {
      "id": "client",
      "line": "Clients"
    },
    {
      "id": "deliverable",
      "line": "Client deliverables",
      "create": true
    },
    {
      "id": "report",
      "line": "Status report drafts",
      "create": true
    },
    {
      "id": "time_entry",
      "line": "Billable time from CSV",
      "create": true
    },
    {
      "id": "invoice",
      "line": "Invoice drafts",
      "create": true
    }
  ],
  "automation": [
    {
      "id": "friday-report",
      "line": "Every Friday, gather mail and draft a status report per client"
    },
    {
      "id": "build-invoice",
      "line": "Build an invoice draft from a client's CSV time"
    },
    {
      "id": "write-invoice",
      "line": "Write an approved invoice, held for approval first"
    }
  ],
  "actions": [
    {
      "id": "friday-report",
      "line": "Draft a Friday status report per client from mail"
    },
    {
      "id": "build-invoice",
      "line": "Roll a client's CSV time into an invoice draft"
    },
    {
      "id": "write-invoice",
      "line": "Write an approved invoice draft, held for approval first"
    }
  ],
  "screens": [
    {
      "id": "desk",
      "line": "Today priorities"
    },
    {
      "id": "deliverables",
      "line": "Deliverables by status"
    },
    {
      "id": "clients",
      "line": "Clients"
    },
    {
      "id": "invoices",
      "line": "Invoice drafts"
    }
  ],
  "agent": {
    "line": "Client desk assistant: finds deliverables, drafts reports and invoices, and asks before any write",
    "actions": [
      "friday-report",
      "build-invoice",
      "write-invoice"
    ]
  }
}

